text.value:
UPDATE dbo.audit_log
SET status = 'SUCCESS',
    end_time = SYSUTCDATETIME(),
    records_written = @{int(activity('Get Gold Notebook Result').output.properties.exitValue)}
WHERE adf_run_id = '@{pipeline().parameters.adf_run_id}'
  AND table_id = @{pipeline().parameters.table_id};

UPDATE ctrl.audit_log
SET status = 'SUCCESS',
    end_time = SYSUTCDATETIME(),
    records_written = @{int(activity('Get Gold Notebook Result').output.properties.exitValue)}
WHERE adf_run_id = '@{pipeline().parameters.adf_run_id}'
  AND table_id = @{pipeline().parameters.table_id};

p_relative_url.value:
@concat(
    activity('Read Table Details').output.firstRow.source_relative_url,
    if(
        equals(
            activity('Read Table Details').output.firstRow.url_parameter_strategy,
            'SINCE_PER_PAGE'
        ),
        concat(
            '?since=',
            formatDateTime(variables('watermark_value'), 'yyyy-MM-ddTHH:mm:ssZ'),
            '&',
            activity('Read Table Details').output.firstRow.source_api_params
        ),
        if(
            equals(
                activity('Read Table Details').output.firstRow.url_parameter_strategy,
                'SORT_UPDATED'
            ),
            concat(
                '?sort=updated&direction=desc&',
                activity('Read Table Details').output.firstRow.source_api_params
            ),
            concat(
                '?',
                activity('Read Table Details').output.firstRow.source_api_params
            )
        )
    )
)

